table.cnt td{vertical-align:middle}table.cnt td.n{white-space:nowrap}table.cnt tr.cn_cat td{background:var(--cream);font-weight:700;font-size:12px;color:var(--navy);padding:5px 8px}table.cnt .cn_in{width:84px;min-height:34px;padding:4px 6px;text-align:right}table.cnt .cn_rm{width:100%;min-width:130px;min-height:34px;padding:4px 6px}
.cnhead{display:grid;grid-template-columns:1fr 150px auto;gap:8px;align-items:center;margin-bottom:6px}.cnhead .i{min-width:0}
.cnlist{display:flex;flex-direction:column;gap:6px;padding-bottom:8px}.cn_catm{font-weight:700;font-size:12px;color:var(--navy);background:var(--cream);padding:5px 8px;border-radius:6px;margin-top:4px}
.cnr{background:#fff;border:1px solid var(--line);border-radius:10px;padding:8px 10px}.cnr1{display:flex;align-items:center;gap:8px;font-size:14px;line-height:1.25}
.cnrm{border:1px solid var(--line);background:#fff;border-radius:8px;width:30px;height:30px;color:var(--mute);flex:none}.cnrm.on{color:var(--navy);border-color:var(--gold);background:var(--cream)}
.cnr2{display:grid;grid-template-columns:1.3fr 1fr 1fr 1fr;gap:6px;margin-top:6px}.cnr3{display:flex;align-items:center;gap:10px;margin-top:6px}.cnr3 label{font-size:12px;color:var(--mute);white-space:nowrap}.cnr3 .cn_in{width:110px;min-height:36px;padding:4px 8px;text-align:right}.cnr3 .cn_d{font-size:14px;margin-left:auto}
.cnk{display:flex;flex-direction:column;min-width:0}.cnk span{font-size:10.5px;color:var(--mute);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cnk b{font-size:13px;font-weight:600;white-space:nowrap}
.cnr .cn_rm{margin-top:6px;min-height:34px;padding:4px 8px;width:100%}
@media(max-width:380px){.cnhead{grid-template-columns:1fr 130px auto}}

